create table private.parent_document_releases (
 code text not null, version integer not null check(version>0), body text not null,
 source_url text not null, source_sha256 text not null, published_at timestamptz not null default now(),
 primary key(code,version)
);
alter table private.parent_document_releases enable row level security;
revoke all on private.parent_document_releases from public,anon,authenticated;
create function private.parent_document_version(p_code text) returns integer
language sql stable security definer set search_path='' as $$
 select coalesce(max(version),1) from private.parent_document_releases where code=p_code
$$;
revoke all on function private.parent_document_version(text) from public,anon;
grant execute on function private.parent_document_version(text) to authenticated,service_role;
insert into private.parent_document_releases(code,version,body,source_url,source_sha256) values('education_contract',2,'ДОГОВОР

ОБ ОКАЗАНИИ ПЛАТНЫХ ОБРАЗОВАТЕЛЬНЫХ УСЛУГ № _____

г. Иркутск                                                                                                     «___» ______________ 2026 г.

Индивидуальный предприниматель Федотова Кристина Владимировна (ИП Федотова К.В.), именуемый в дальнейшем «Исполнитель», действующий на основании ОГРНИП 325385000099892, зарегистрированный Межрайонной инспекцией Федеральной налоговой службы № 17 по Иркутской области от 10.09.2025 года, осуществляющая образовательную деятельность на основании лицензии № Л035-01220-38/03861554 от 28.11.2025, с одной стороны, и

Гражданин(ка) _________________________________________________________, паспорт: серия ____ № ________, выдан __________________________________________ «__» _______________г., адрес регистрации: _____________________________________________, телефон: ________________________________, действующий(ая) в интересах несовершеннолетнего(ей) ____________________________________ именуемый в дальнейшем Обучающийся, ______________ года рождения, свидетельство о рождении: ______________________________, именуемый(ая) в дальнейшем Заказчик, с другой стороны, совместно именуемые Стороны, заключили настоящий Договор о нижеследующем:

1. ПРЕДМЕТ ДОГОВОРА

1.1. Исполнитель обязуется оказать Обучающемуся платные образовательные услуги по дополнительной общеобразовательной общеразвивающей программе художественной направленности в модельном агентстве «Open Stars»: «МИР ТЕАТРА ДЛЯ ДЕТЕЙ» (далее — Программа), а Заказчик обязуется принять и оплатить эти услуги в полном объеме.

1.2. Характеристика образовательной программы:

Форма обучения: очна-заочная.

Объем программы: 108 учебных часов или 180 учебных часов.

Продолжительность одного учебного часа: 30 минут для групп «малыши», 45 минут для групп «7 лет+».

Срок освоения: 9 (девять) месяцев.

Даты начала и окончания обучения: с «__» _________ 2026 г. по «__» _________ 2027 г.

Место проведения занятий: 

Очные образовательные услуги проводятся по одному из адресов по выбору Заказчика: 

664081, г. Иркутск, ул. Депутатская, д. 84/1;

664033, г. Иркутск, ул. Лермонтова, д. 281/1;

664053, г. Иркутск, ул. Баумана, д. 241

Заочные образовательные услуги оказываются дистанционно с использованием информационно-телекоммуникационной сети «Интернет». Заочные занятия проводятся с использованием электронной информационно-образовательной среды Исполнителя: адаптивной платформы CoreApp (https://coreapp.ai/) и сервиса видеоконференций Яндекс.Телемост (https://telemost.yandex.ru/).

1.3. Режим занятий: 

1.3.1. Занятия проводятся:

1 раз в неделю (3 учебных часа) при выборе программы 108 часов. 

2 раза в неделю (5 учебных часов) при выборе программы 180 часов. 

Общее количество учебных часов в месяц не может превышать 12 часов при выборе программы 108 часов и 20 часов при выборе программы 180 часов. Продолжительность и количество занятий определяются утвержденным Исполнителем учебным планом и расписанием, с которыми Заказчик ознакомлен до подписания настоящего Договора.

2. СТОИМОСТЬ ОБУЧЕНИЯ И ПОРЯДОК РАСЧЕТОВ

2.1. Полная стоимость образовательных услуг за весь срок обучения (9 месяцев) составляет:

54 000,00 (пятьдесят четыре тысячи) рублей при выборе программы 108 часов.

99 000,00 (девяносто девять тысяч) рублей при выборе программы 180 часов.

2.2. Стоимость одного календарного месяца обучения составляет 6 000,00 (шесть тысяч) рублей и включает 12 (двенадцать) учебных часов (занятий) в соответствии с учебным планом или 11 000,00 (одиннадцать тысяч) рублей в месяц и включает 20 (двадцать) учебных часов (занятий) в соответствии с учебным планом.

2.3. При оплате за счет собственных средств, оплата производится ежемесячно, не позднее 10-го числа текущего месяца, авансовым платежом в размере стоимости одного месяца обучения (п. 2.2 Договора) путём перечисления денежных средств на расчётный счёт Исполнителя.

2.4. При оплате с использованием средств материнского (семейного) капитала, оплата образовательных услуг осуществляется за счет средств материнского (семейного) капитала путем безналичного перечисления территориальным органом Социального фонда России (СФР) на расчетный счет Исполнителя на основании удовлетворенного заявления Заказчика.

2.4.1. Заказчик обязуется предоставить Исполнителю все необходимые документы для заключения соглашения об информационном взаимодействии с СФР.

2.4.2. В случае отказа СФР в перечислении средств или перечисления их в меньшем размере, Заказчик обязан оплатить образовательные услуги за счет собственных средств в порядке, установленном п. 2.3 Договора.

2.4.3. Задержка перечисления средств со стороны СФР при своевременном предоставлении Заказчиком всех необходимых документов не является просрочкой Заказчика и не может служить основанием для ограничения доступа Обучающегося к занятиям.

2.4.4. При прекращении действия настоящего Договора до истечения срока его действия неиспользованные средства материнского (семейного) капитала, перечисленные Исполнителю СФР, подлежат возврату Исполнителем в территориальный орган СФР, осуществивший перечисление, в порядке и сроки, установленные законодательством РФ (в течение 5 банковских дней). Средства, внесенные Заказчиком самостоятельно, возвращаются Заказчику в соответствии с разделом 5 настоящего Договора.

3. ПРАВА И ОБЯЗАННОСТИ СТОРОН

3.1. Исполнитель обязуется:

3.1.1. Зачислить Обучающегося в состав обучающихся и обеспечить образовательный процесс в соответствии с Программой, учебным планом и расписанием.

3.1.2. Обеспечить Обучающегося необходимыми наглядными пособиями и материалами во время обучения.

3.1.3. При условии полного освоения Программы выдать Обучающемуся документ (диплом негосударственного образца) о прохождении обучения в модельном агентстве «Open Stars», не подтверждающий присвоение квалификации.

3.1.4. Предоставлять Заказчику достоверную информацию о себе и об оказываемых услугах, а также знакомить с Правилами внутреннего распорядка и техники безопасности.

3.2. Заказчик обязуется:

3.2.1. Своевременно и в полном объеме оплачивать услуги Исполнителя в порядке, установленном разделом 2 настоящего Договора. Обязанность по оплате лежит на Заказчике, а не на Обучающемся.

3.2.2. Обеспечить посещение Обучающимся занятий в указанное Исполнителем время.

3.2.3. Уведомлять Исполнителя о причинах пропуска занятий не позднее дня пропуска (болезнь, семейные обстоятельства и т.д.) с предоставлением подтверждающих документов.

3.2.4. Соблюдать и обеспечить соблюдение Обучающимся Программы, Правил внутреннего распорядка, утвержденных Исполнителем, и правил техники безопасности.

3.2.5. Бережно относиться к имуществу Исполнителя.

3.2.6. Обеспечить наличие у Обучающегося технических средств (персональный компьютер, ноутбук, планшет, веб-камера, микрофон) и доступа к сети «Интернет» со скоростью, достаточной для участия в онлайн-занятиях на платформах, указанных в образовательной программе (Яндекс.Телемост, CoreApp).

4. ОТВЕТСТВЕННОСТЬ СТОРОН

4.1. Стороны несут ответственность за неисполнение или ненадлежащее исполнение своих обязательств в соответствии с действующим законодательством РФ.

4.2. Стороны освобождаются от ответственности за неисполнение обязательств вследствие обстоятельств непреодолимой силы (форс-мажор).

4.3. В случае причинения Обучающимся ущерба имуществу Исполнителя (порча оборудования, реквизита, мебели и иного имущества) Заказчик возмещает Исполнителю реальный ущерб в размере стоимости повреждённого или утраченного имущества (с учётом износа) либо стоимости его восстановительного ремонта.

4.4. Размер ущерба определяется на основании акта, составляемого Сторонами, либо, при отказе Заказчика от подписания акта, — на основании документов, подтверждающих стоимость имущества и характер повреждений (товарные чеки, счета, заключение специалиста).

4.5. Заказчик обязуется возместить ущерб в течение 30 (тридцати) календарных дней с даты подписания акта (или получения письменной претензии Исполнителя с приложением подтверждающих документов).

5. ИЗМЕНЕНИЕ И РАСТОРЖЕНИЕ ДОГОВОРА

5.1. В случае пропуска Обучающимся отдельных занятий Договор продолжает действовать. Пропущенные занятия могут быть отработаны с другой группой в удобное для Заказчика время в течение 30 календарных дней. В случае пропуска запланированного занятия по уважительной причине (при предоставлении справки) ее отработка осуществляется за счет Исполнителя. При пропуске без уважительной причины — за счет Заказчика.

5.2. Заказчик вправе в любое время отказаться от исполнения настоящего Договора, направив Исполнителю письменное заявление. Договор считается прекращенным с даты, указанной в заявлении, но не ранее даты его получения Исполнителем.

5.3. При расторжении Договора по инициативе Заказчика Исполнитель удерживает cтоимость фактически оказанных образовательных услуг и определяет их пропорционально объёму проведённых занятий (учебных часов) исходя из полной стоимости программы и общего количества учебных часов, предусмотренных учебным планом. Остаток денежных средств возвращается Заказчику в течение 10 (десяти) рабочих дней с даты подписания Сторонами соглашения о расторжении или получения Исполнителем заявления Заказчика.

5.4. Возврат средств маткапитала. В случае расторжения Договора неиспользованные средства материнского капитала возвращаются Исполнителем в территориальный орган СФР в порядке, установленном законодательством (п. 2.4.4 Договора).

5.5. При расчёте суммы возврата не учитываются штрафы, комиссии и иные суммы, удерживаемые Исполнителем исключительно за факт отказа Заказчика от исполнения Договора.

6. ПРОЧИЕ УСЛОВИЯ

6.1. Договор вступает в силу с момента подписания и действует до полного исполнения Сторонами своих обязательств.

6.2. Все изменения и дополнения к Договору действительны, если они оформлены в письменной форме и подписаны Сторонами.

6.3. Ни одна из Сторон не вправе передавать свои обязательства по Договору третьей стороне без письменного согласия другой Стороны.

6.4. Договор составлен в двух экземплярах, имеющих одинаковую юридическую силу, по одному для каждой из Сторон.

6.5. По письменному соглашению Сторон Обучающийся может быть переведён в другую группу с соответствующим изменением сроков обучения. Перевод оформляется дополнительным соглашением к настоящему Договору.

6.6. Место проведения занятий может быть изменено по письменному соглашению Сторон. Исполнитель обязан уведомить Заказчика о предлагаемом изменении не менее чем за 10 календарных дней. Изменение вступает в силу с даты подписания соответствующего дополнительного соглашения. Изменение места нахождения Исполнителя не влияет на условия оказания дистанционных услуг.

6.7. Приложения:

6.7.1. Приложение №1: Программа обучения.

6.7.2. Приложение №2: Учебный план.

6.7.3. Приложение №3: Расписание занятий.

